SELECT s.student_id AS studentId, s.student_name AS studentName, s.billing_phone AS billingPhone, (pa.parent_tel_first + pa.parent_tel_middle + pa.parent_tel_last) AS parentPhone, p.payment_key AS paymentKey, SUM(pd.amount) AS amount FROM erp_student s JOIN erp_parent pa ON pa.student_id = s.student_id JOIN erp_payment p ON p.student_id = s.student_id JOIN erp_payment_detail pd ON pd.payment_key = p.payment_key WHERE (pa.parent_tel_first + pa.parent_tel_middle + pa.parent_tel_last) IN
#{phone}
AND p.yy = #{yy} AND p.mm = #{mm} AND pd.item_type = #{type} GROUP BY s.student_id, s.student_name,s.billing_phone, (pa.parent_tel_first + pa.parent_tel_middle + pa.parent_tel_last), p.payment_key

