mapper.select:
WITH classInfo AS (SELECT ta.student_id, t.user_code, u.user_name AS teacherName, cc.class_type, STUFF( (SELECT ', ' + cc2.class_name FROM erp_time_table_assign ta2 JOIN erp_time_table t2 ON ta2.time_table_key = t2.time_table_key JOIN erp_class_code cc2 ON t2.class_key = cc2.class_key WHERE ta2.student_id = ta.student_id AND t2.yy = #{yy} AND t2.mm = #{mm} AND t2.user_code = t.user_code FOR XML PATH ('')), 1, 2, '' ) AS subject FROM erp_time_table_assign ta JOIN erp_time_table t ON ta.time_table_key = t.time_table_key JOIN erp_class_code cc ON t.class_key = cc.class_key JOIN erp_user u ON t.user_code = u.user_code WHERE t.yy = #{yy} AND t.mm = #{mm} AND cc.class_type IN ('1', '2') AND (#{userCode} = 'all' OR t.user_code = #{userCode}) GROUP BY ta.student_id, t.user_code, u.user_name, cc.class_type)
SELECT s.student_name AS studentName, ci.subject AS subject, ci.teacherName AS teacherName, ci.user_code AS teacherCode, amt.billAmount AS billPrice,
/* 결제금액 (item_type 기준 단일 계산) */ pay.calc_paid_amount AS paidAmount,
/* 미납금액 (결제금액 기준) */ CASE WHEN amt.billAmount - pay.calc_paid_amount < 0 THEN 0 ELSE amt.billAmount - pay.calc_paid_amount END AS unpaidAmount,
/* 결제여부 (결제금액 기준) */ CASE WHEN amt.billAmount = 0 THEN '할인' WHEN pay.calc_paid_amount = 0 THEN '미결제' WHEN pay.calc_paid_amount >= amt.billAmount THEN '결제완료' ELSE '부분결제' END AS payStatus
FROM erp_payment p JOIN erp_student s ON p.student_id = s.student_id LEFT JOIN erp_parent pa ON s.student_id = pa.student_id JOIN classInfo ci ON s.student_id = ci.student_id
JOIN (SELECT payment_key, user_code, SUM(amount) AS billAmount, item_type FROM erp_payment_detail WHERE item_type = #{itemType} AND (#{userCode} = 'all' OR user_code = #{userCode}) GROUP BY payment_key, user_code, item_type) amt ON p.payment_key = amt.payment_key AND ci.user_code = amt.user_code
LEFT JOIN (SELECT payment_key, status, bill_id FROM (SELECT payment_key, status, ROW_NUMBER() OVER (PARTITION BY payment_key ORDER BY created_at DESC) as rn, bill_id FROM erp_payment_bill WHERE bill_type = #{itemType}) sub WHERE rn = 1) pb ON p.payment_key = pb.payment_key LEFT JOIN (SELECT payment_key, SUM(card_amount + cash_amount + transfer_amount) AS manual_amount FROM erp_payment_manual GROUP BY payment_key) pm ON p.payment_key = pm.payment_key LEFT JOIN (SELECT payment_key, SUM(amount) AS bill_amount FROM erp_payment_bill WHERE status = 'approved' AND bill_type = #{itemType} GROUP BY payment_key) pb_pay ON p.payment_key = pb_pay.payment_key CROSS APPLY (SELECT CASE WHEN amt.item_type = 'BOOK_FEE' THEN COALESCE(pb_pay.bill_amount, 0) ELSE COALESCE(pm.manual_amount, 0) + COALESCE(pb_pay.bill_amount, 0) END AS calc_paid_amount) pay
WHERE p.center_code = #{centerCode} AND p.yy = #{yy} AND p.mm = #{mm}
GROUP BY s.student_name, ci.subject, ci.teacherName, ci.user_code, amt.billAmount, pay.calc_paid_amount
ORDER BY ci.teacherName, s.student_name;

